def read_rss_bytes() -> int:
    """当前进程的常驻集大小。

    刻意不用 `psutil`：生产依赖必须随离线介质交付，为一条压测引一个新依赖不值得；
    而 `ctypes` + `/proc` 两条路已经覆盖开发与现场的全部平台。
    """
    if sys.platform == "win32":
        counters = _WindowsProcessMemoryCounters()
        counters.cb = ctypes.sizeof(counters)
        handle = ctypes.windll.kernel32.GetCurrentProcess()      # type: ignore[attr-defined]
        ok = ctypes.windll.psapi.GetProcessMemoryInfo(           # type: ignore[attr-defined]
            ctypes.c_void_p(handle), ctypes.byref(counters), counters.cb
        )
        if not ok:
            raise MemoryProbeUnavailable(
                f"GetProcessMemoryInfo 失败（GetLastError={ctypes.get_last_error()}）"
            )
        return int(counters.WorkingSetSize)

    statm = "/proc/self/statm"
    if os.path.exists(statm):
        with open(statm, encoding="ascii") as handle:
            resident_pages = int(handle.read().split()[1])
        return resident_pages * os.sysconf("SC_PAGE_SIZE")

    raise MemoryProbeUnavailable(
        f"平台 {sys.platform} 上读不到 RSS。这条完成判定不能跳过——"
        f"请补一个本平台的探针，或在该平台上不声称通过内存稳定性验证"
    )


def sample_rss() -> int:
    """测量前先收一轮，把「还没回收」与「回收不了」分开。"""
    gc.collect()
    return read_rss_bytes()

